import re
import os

def task_func(request):
    if not isinstance(request, str):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    first_line = request.splitlines()[0] if request.splitlines() else ""
    match = re.fullmatch(r"GET\s+(/\S*)\s+HTTP/\d(?:\.\d)?", first_line)

    if not match:
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    requested_path = match.group(1).split("?", 1)[0]
    filename = requested_path.lstrip("/")

    if not filename:
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    server_directory = os.path.abspath(os.getcwd())
    file_path = os.path.abspath(os.path.join(server_directory, filename))

    try:
        if os.path.commonpath((server_directory, file_path)) != server_directory:
            return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"
    except ValueError:
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    if not os.path.isfile(file_path):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            content = file.read()
    except (OSError, UnicodeDecodeError):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    content_length = len(content.encode("utf-8"))
    return (
        f"HTTP/1.1 200 OK\r\n"
        f"Content-Length: {content_length}\r\n"
        f"\r\n"
        f"{content}"
    )

