import base64

def task_func(raw_string, filename, output_dir):
    decoded_data = base64.b64decode(raw_string).decode("utf-8")
    data = json.loads(decoded_data)

    file_path = os.path.join(output_dir, filename)
    os.makedirs(output_dir, exist_ok=True)

    if isinstance(data, list):
        rows = data
    elif isinstance(data, dict):
        rows = [data]
    else:
        rows = [{"value": data}]

    with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
        if rows and all(isinstance(row, dict) for row in rows):
            fieldnames = []
            for row in rows:
                for key in row:
                    if key not in fieldnames:
                        fieldnames.append(key)

            writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerows(rows)
        else:
            writer = csv.writer(csv_file)
            writer.writerow(["value"])
            for row in rows:
                writer.writerow([row])

    return file_path

import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    """Convert newline-separated product data into a DataFrame."""
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]

    if not isinstance(s, str):
        raise TypeError("s must be a string")

    rng = random.Random(seed)
    product_names = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    code_to_product = {}
    rows = []

    for line_number, line in enumerate(s.splitlines(), start=1):
        line = line.rstrip()
        if not line.strip():
            continue

        parts = re.split(r"\s+", line.strip(), maxsplit=4)
        if len(parts) < 4:
            raise ValueError(
                f"Line {line_number} must contain at least ID, quantity, code, and price"
            )

        identifier, quantity, code, price = parts[:4]
        description = parts[4].rstrip() if len(parts) == 5 else ""

        try:
            identifier = int(identifier)
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Line {line_number} contains a non-integer ID, quantity, or price"
            ) from exc

        if code not in code_to_product:
            code_to_product[code] = rng.choice(product_names)

        rows.append(
            {
                "ID": identifier,
                "Quantity": quantity,
                "Code": code,
                "Price": price,
                "Product": code_to_product[code],
                "Description": description,
            }
        )

    return pd.DataFrame(rows, columns=columns)

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    current_pid = os.getpid()
    processes = []

    if os.name == "nt":
        result = subprocess.run(
            ["tasklist", "/FO", "CSV", "/NH"],
            capture_output=True,
            text=True,
            check=False,
        )

        for line in result.stdout.splitlines():
            fields = [field.strip('"') for field in line.split('","')]
            if len(fields) >= 2 and fields[0] == process_name:
                try:
                    pid = int(fields[1])
                    if pid != current_pid:
                        processes.append(pid)
                except ValueError:
                    continue
    else:
        result = subprocess.run(
            ["pgrep", "-x", process_name],
            capture_output=True,
            text=True,
            check=False,
        )

        for line in result.stdout.splitlines():
            try:
                pid = int(line.strip())
                if pid != current_pid:
                    processes.append(pid)
            except ValueError:
                continue

    stopped = 0
    for pid in processes:
        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except (ProcessLookupError, PermissionError, OSError):
            continue

    time.sleep(1)
    return stopped

import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return "/fake/backup/path"


def task_func(directory):
    """
    Back up all contents of `directory`, then remove the original contents.

    Returns:
        tuple[str, list]: The backup directory path and any errors encountered.
    """
    backup_directory = get_unique_backup_dir()
    errors = []

    if not os.path.isdir(directory):
        return backup_directory, [f"Source directory does not exist: {directory}"]

    try:
        os.makedirs(backup_directory, exist_ok=False)
    except OSError as error:
        return backup_directory, [f"Could not create backup directory: {error}"]

    try:
        entries = list(os.scandir(directory))
    except OSError as error:
        return backup_directory, [f"Could not read source directory: {error}"]

    for entry in entries:
        source_path = entry.path
        destination_path = os.path.join(backup_directory, entry.name)

        try:
            if entry.is_dir(follow_symlinks=False):
                shutil.copytree(
                    source_path,
                    destination_path,
                    symlinks=True,
                )
                shutil.rmtree(source_path)
            else:
                shutil.copy2(
                    source_path,
                    destination_path,
                    follow_symlinks=False,
                )
                os.unlink(source_path)
        except OSError as error:
            errors.append(f"{source_path}: {error}")

    return backup_directory, errors

