import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist: {src_folder}",
            "failed_files": [],
        }

    files = [
        path for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    ]

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        failed_files = [os.path.basename(path) for path in files]
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": failed_files,
        }

    for source_path in files:
        filename = os.path.basename(source_path)
        compressed_name = f"{filename}.gz"
        destination_path = os.path.join(dst_folder, compressed_name)
        temporary_path = f"{destination_path}.tmp"

        try:
            with open(temporary_path, "wb") as output_file:
                process = subprocess.Popen(
                    ["gzip", "-c", source_path],
                    stdout=output_file,
                    stderr=subprocess.PIPE,
                )
                _, stderr = process.communicate()

            if process.returncode != 0:
                raise RuntimeError(
                    stderr.decode(errors="replace").strip()
                    or "gzip returned a non-zero exit code"
                )

            shutil.move(temporary_path, destination_path)
        except (OSError, subprocess.SubprocessError, RuntimeError):
            failed_files.append(filename)
            try:
                if os.path.exists(temporary_path):
                    os.remove(temporary_path)
            except OSError:
                pass

    success = not failed_files
    if success:
        message = f"Successfully compressed and moved {len(files)} file(s)."
    else:
        message = (
            f"Failed to compress or move {len(failed_files)} file(s): "
            + ", ".join(failed_files)
        )

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }

import random
import string
import pandas as pd


def task_func(data_list, seed=0):
    rng = random.Random(seed)
    original_strings = list(data_list)
    modified_strings = []

    for value in original_strings:
        text = value
        segments = []
        start = 0

        for index in range(len(text) + 1):
            if index == len(text) or text[index] == ",":
                if start < index:
                    segments.append((start, index))
                start = index + 1

        if segments:
            segment_start, segment_end = rng.choice(segments)
            replacement = "".join(
                rng.choice(string.ascii_lowercase)
                for _ in range(segment_end - segment_start)
            )
            text = (
                text[:segment_start]
                + replacement
                + text[segment_end:]
            )

        modified_strings.append(text)

    return pd.DataFrame({
        "Original String": original_strings,
        "Modified String": modified_strings,
    })

import os
import glob
import shutil

def task_func(directory, archive_dir='archive'):
    """Move all JSON files in directory to archive_dir.

    Returns:
        tuple: (success, errors), where success is True if every JSON file
        was moved successfully, and errors contains one message per failure.
    """
    json_files = [
        path for path in glob.glob(os.path.join(directory, '*.json'))
        if os.path.isfile(path)
    ]
    errors = []

    if not json_files:
        return True, errors

    try:
        os.makedirs(archive_dir, exist_ok=True)
    except OSError as exc:
        return False, [
            f"Failed to move {file_path}: unable to create archive directory: {exc}"
            for file_path in json_files
        ]

    for file_path in json_files:
        destination = os.path.join(archive_dir, os.path.basename(file_path))
        try:
            shutil.move(file_path, destination)
        except (OSError, shutil.Error) as exc:
            errors.append(f"Failed to move {file_path}: {exc}")

    return not errors, errors

