import re
import json
from collections import Counter

def task_func(json_str, top_n=10):
    """Extract URLs from a JSON-serialized dictionary and count occurrences."""
    data = json.loads(json_str)

    url_pattern = re.compile(
        r"https?://[A-Za-z0-9.-]+(?::\d+)?"
        r"(?:[/?#][A-Za-z0-9._~:/?#\[\]@!$&'()*+,;=%-]*)?"
    )

    def extract(value):
        if isinstance(value, str):
            return url_pattern.findall(value)
        if isinstance(value, dict):
            urls = []
            for key, item in value.items():
                urls.extend(extract(key))
                urls.extend(extract(item))
            return urls
        if isinstance(value, (list, tuple)):
            urls = []
            for item in value:
                urls.extend(extract(item))
            return urls
        return []

    if top_n is None:
        top_n = 10
    if not isinstance(top_n, int) or top_n < 0:
        raise ValueError("top_n must be a non-negative integer or None")

    return dict(Counter(extract(data)).most_common(top_n))

