import json
import re
import pandas as pd


def task_func(json_str):
    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    number_pattern = re.compile(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?")

    def normalize(value):
        if isinstance(value, bool):
            return value

        if isinstance(value, (int, float)):
            return float(value * 2)

        if isinstance(value, list):
            return [normalize(item) for item in value]

        if isinstance(value, str):
            matches = number_pattern.findall(value)
            if not matches:
                return value

            numbers = [float(match) * 2 for match in matches]
            return numbers[0] if len(numbers) == 1 and value.strip() == matches[0] else numbers

        return value

    normalized = {key: normalize(value) for key, value in data.items()}

    try:
        return pd.DataFrame(normalized)
    except (TypeError, ValueError):
        return pd.DataFrame()

