def task_func(example_str):
    depth = 0
    extracted_chars = []

    for char in example_str:
        if char == "[":
            depth += 1
        elif char == "]":
            if depth > 0:
                depth -= 1
        elif depth == 0:
            extracted_chars.append(char)

    extracted_text = "".join(extracted_chars).strip()
    if not extracted_text:
        return {}

    vectorizer = TfidfVectorizer()
    tfidf_matrix = vectorizer.fit_transform([extracted_text])

    words = vectorizer.get_feature_names_out()
    scores = np.asarray(tfidf_matrix.toarray()).ravel()

    return dict(zip(words, scores))

