import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    start_time = time.time()
    cpu_usage_data = []

    while time.time() - start_time < duration:
        if platform.system() == "Windows":
            command = "wmic cpu get loadpercentage"
        else:
            command = "top -bn1 | grep 'Cpu(s)'"

        output = subprocess.check_output(command, shell=True)
        if isinstance(output, bytes):
            output = output.decode(errors="replace")

        if platform.system() == "Windows":
            cpu_usage = None
            for line in output.splitlines():
                try:
                    cpu_usage = float(line.strip())
                    break
                except ValueError:
                    continue
            if cpu_usage is None:
                raise ValueError("Unable to parse CPU usage")
        else:
            idle_position = output.find("id")
            if idle_position == -1:
                raise ValueError("Unable to parse CPU usage")

            before_idle = output[:idle_position].rstrip()
            idle_value = before_idle.rsplit(",", 1)[-1].split()[0]
            cpu_usage = 100.0 - float(idle_value)

        cpu_usage_data.append(
            {
                "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
                "cpu_usage": cpu_usage,
            }
        )

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w") as logfile:
            json.dump(cpu_usage_data, logfile, indent=2)
    except IOError:
        return None

    return LOGFILE_PATH

