def task_func(json_data: str, key_path: list):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("The data string is empty or invalid.")

    try:
        data = json.loads(
            json_data,
            parse_constant=lambda value: (_ for _ in ()).throw(
                ValueError(f"Invalid JSON constant: {value}")
            ),
        )
    except (json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError("The data string is corrupted or invalid.") from exc

    current = data
    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(key)
        current = current[key]

    values = []

    def collect_numbers(item):
        if isinstance(item, bool):
            return
        if isinstance(item, (int, float)):
            if np.isfinite(item):
                values.append(float(item))
            return
        if isinstance(item, list):
            for value in item:
                collect_numbers(value)
        elif isinstance(item, dict):
            for value in item.values():
                collect_numbers(value)

    collect_numbers(current)

    if not values:
        raise ValueError("No numeric data found.")

    numeric_data = pd.Series(values, dtype=float)

    fig, ax = plt.subplots()
