def task_func(data, target_column, test_size=0.2, random_state=0) -> float:
    if not isinstance(data, pd.DataFrame):
        raise ValueError("data must be a DataFrame")

    if data.empty:
        raise ValueError("data must not be empty")

    try:
        target_exists = target_column in data.columns
    except TypeError:
        target_exists = False

    if not target_exists:
        raise ValueError("target_column must be a column of data")

    if isinstance(random_state, bool) or not isinstance(
        random_state, (int, np.integer)
    ):
        raise ValueError("random_state must be an integer")

    if isinstance(test_size, bool):
        raise ValueError("test_size must be between 0 and 1")

    try:
        valid_test_size = 0 < float(test_size) < 1
    except (TypeError, ValueError):
        valid_test_size = False

    if not valid_test_size:
        raise ValueError("test_size must be between 0 and 1")

    if not all(pd.api.types.is_numeric_dtype(dtype) for dtype in data.dtypes):
        raise ValueError("data must contain only numeric values")

    try:
        numeric_data = data.to_numpy(dtype=float)
    except (TypeError, ValueError):
        raise ValueError("data must contain only numeric values")

    if not np.isfinite(numeric_data).all():
        raise ValueError("data must contain only numeric values")

    X = data.drop(columns=[target_column])
    y = data[target_column]

    X_train, X_test, y_train, y_test = train_test_split(
        X,
        y,
        test_size=test_size,
        random_state=random_state,
    )

    model = LinearRegression()
    model.fit(X_train, y_train)

    return float(model.score(X_test, y_test))

