import re
import glob
from docx import Document


def task_func(directory_path: str) -> int:
    """Process all .docx files in a directory and escape double quotes."""
    file_paths = sorted(
        set(glob.glob(f"{directory_path}/*.docx"))
        | set(glob.glob(f"{directory_path}/*.DOCX"))
    )

    def process_paragraph(paragraph) -> None:
        for run in paragraph.runs:
            run.text = re.sub(r'"', r'\\"', run.text)

    def process_table(table) -> None:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    process_paragraph(paragraph)
                for nested_table in cell.tables:
                    process_table(nested_table)

    for file_path in file_paths:
        document = Document(file_path)

        for paragraph in document.paragraphs:
            process_paragraph(paragraph)
        for table in document.tables:
            process_table(table)

        processed_parts = set()
        for section in document.sections:
            for container in (
                section.header,
                section.first_page_header,
                section.even_page_header,
                section.footer,
                section.first_page_footer,
                section.even_page_footer,
            ):
                part_id = id(container.part)
                if part_id in processed_parts:
                    continue
                processed_parts.add(part_id)

                for paragraph in container.paragraphs:
                    process_paragraph(paragraph)
                for table in container.tables:
                    process_table(table)

        document.save(file_path)

    return len(file_paths)

