from sklearn.cluster import KMeans
from sklearn.feature_extraction.text import CountVectorizer


def task_func(df):
    """Filter articles with 'how' or 'what' in the title and cluster them."""
    if df.empty:
        return []

    title_column = "title"
    content_column = "content"

    if title_column not in df.columns:
        return []

    titles = df[title_column].fillna("").astype(str)
    mask = titles.str.contains(r"\b(?:how|what)\b", case=False, regex=True)
    filtered = df.loc[mask]

    if filtered.empty:
        return []

    if content_column in filtered.columns:
        texts = filtered[content_column].fillna("").astype(str)
    else:
        texts = filtered[title_column].fillna("").astype(str)

    vectorizer = CountVectorizer()
    try:
        vectors = vectorizer.fit_transform(texts)
    except ValueError:
        return [0] * len(filtered)

    n_clusters = min(2, len(filtered))
    if n_clusters == 1:
        return [0]

    model = KMeans(n_clusters=n_clusters, random_state=42, n_init=10)
    return model.fit_predict(vectors).tolist()

