                        not inside_brackets
                        and isinstance(key, str)
                        and re.fullmatch(r"name", key, re.IGNORECASE)
                        and isinstance(item, str)
                    ):
                        names.append(item)
                    extract(item, inside_brackets)
            elif isinstance(value, list):
