import xml.etree.ElementTree as ET
import csv


def task_func(xml_content, output_csv_path):
    root = ET.fromstring(xml_content)

    def element_value(element):
        return "".join(element.itertext()).strip()

    records = []
    fieldnames = []

    children = list(root)

    if children and all(not list(child) for child in children):
        records.append({child.tag: element_value(child) for child in children})
        fieldnames = [child.tag for child in children]
    else:
        for record_element in children:
            row = {}
            for field in record_element:
                row[field.tag] = element_value(field)
                if field.tag not in fieldnames:
                    fieldnames.append(field.tag)
            records.append(row)

    try:
        with open(output_csv_path, "w", newline="", encoding="utf-8") as csv_file:
            writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
            if fieldnames:
                writer.writeheader()
                writer.writerows(records)
    except OSError as exc:
        raise IOError(f"Unable to write CSV file: {exc}") from exc

