import pandas as pd
import numpy as np
from numbers import Integral


def task_func(L):
    if not isinstance(L, list):
        raise TypeError("L must be a list of lists of integers")

    for sublist in L:
        if not isinstance(sublist, list):
            raise TypeError("L must be a list of lists of integers")
        if any(isinstance(value, bool) or not isinstance(value, Integral)
               for value in sublist):
            raise TypeError("L must be a list of lists of integers")

    nonempty = [np.asarray(sublist) for sublist in L if sublist]

    if nonempty:
        values = np.concatenate(nonempty)
        unique_values = np.unique(values)

        if len(unique_values) == 1:
            value = float(unique_values[0])
            bins = np.array([value - 0.5, value + 0.5])
        else:
            unique_float = unique_values.astype(float)
            midpoints = (unique_float[:-1] + unique_float[1:]) / 2
            first_edge = unique_float[0] - (midpoints[0] - unique_float[0])
            last_edge = unique_float[-1] + (unique_float[-1] - midpoints[-1])
            bins = np.concatenate(([first_edge], midpoints, [last_edge]))
    else:
        values = np.array([], dtype=int)
        bins = 1

    return pd.Series(values).hist(bins=bins, rwidth=0.8)

