import os
import sys
import importlib
from pkgutil import iter_modules


def task_func(package_name):
    try:
        package = importlib.import_module(package_name)
    except ImportError as exc:
        raise ImportError(
            f"Package '{package_name}' could not be found. "
            f"Please install it with: pip install {package_name}"
        ) from exc

    package_paths = getattr(package, "__path__", None)
    if package_paths is None:
        raise ImportError(
            f"'{package_name}' is not a package. "
            f"Please install it with: pip install {package_name}"
        )

    module_names = []
    for package_path in package_paths:
        if package_path not in sys.path:
            sys.path.append(os.fspath(package_path))

        for _, module_name, _ in iter_modules([package_path]):
            if module_name not in module_names:
                module_names.append(module_name)

    return module_names

from collections import Counter
from sklearn.cluster import KMeans
import matplotlib.pyplot as plt


def task_func(df, n_clusters=3, random_state=None, n_init=10):
    """Identify duplicate points, cluster unique points, and plot the results."""
    if df.empty:
        raise ValueError("The DataFrame must not be empty.")
    if "cluster" in df.columns:
        raise ValueError("The input DataFrame must not already contain a 'cluster' column.")
    if not isinstance(n_clusters, int) or isinstance(n_clusters, bool) or n_clusters < 1:
        raise ValueError("n_clusters must be a positive integer.")

    point_counts = Counter(
        df.itertuples(index=False, name=None)
    )
    duplicate_counts = Counter(
        {point: count for point, count in point_counts.items() if count > 1}
    )

    unique_df = df.drop_duplicates().copy()

    if n_clusters > len(unique_df):
        raise ValueError(
            "n_clusters cannot exceed the number of unique points."
        )

    model = KMeans(
        n_clusters=n_clusters,
        random_state=random_state,
        n_init=n_init,
    )
    unique_df["cluster"] = model.fit_predict(unique_df)

    fig, ax = plt.subplots()

    if unique_df.shape[1] - 1 >= 2:
        x_values = unique_df.iloc[:, 0]
        y_values = unique_df.iloc[:, 1]
    elif unique_df.shape[1] - 1 == 1:
        x_values = unique_df.iloc[:, 0]
        y_values = [0] * len(unique_df)
    else:
        raise ValueError("The DataFrame must contain at least one point dimension.")

    ax.scatter(x_values, y_values, c=unique_df["cluster"], cmap="viridis")
    ax.set_xlabel(str(df.columns[0]))
    ax.set_ylabel(str(df.columns[1]) if len(df.columns) > 1 else "value")
    ax.set_title("KMeans Clusters")

    return duplicate_counts, unique_df, ax

