def task_func(
    start_time,
    end_time,
    step,
    columns=["Timestamp", "Sensor1", "Sensor2", "Sensor3", "SensorStatus"],
    sensor_statuses=["OK", "MAINTENANCE_REQUIRED", "ERROR"],
    random_seed=42,
):
    """Generate artificial sensor readings for a range of timestamps."""
    if len(columns) != 5:
        raise ValueError("columns must contain exactly five names.")
    if not sensor_statuses:
        raise ValueError("sensor_statuses must not be empty.")

    start = pd.Timestamp(start_time)
    end = pd.Timestamp(end_time)

    if isinstance(step, (int, float, np.integer, np.floating)):
        if step <= 0:
            raise ValueError("step must be positive.")
        frequency = pd.to_timedelta(step, unit="s")
    else:
        frequency = pd.Timedelta(step)
        if frequency <= pd.Timedelta(0):
            raise ValueError("step must be positive.")

    timestamps = pd.date_range(start=start, end=end, freq=frequency)
    seconds = np.array([timestamp.timestamp() for timestamp in timestamps])

    rng = np.random.default_rng(random_seed)
    noise = lambda: rng.normal(0.0, 0.01, len(timestamps))

    return pd.DataFrame(
        {
            columns[0]: timestamps,
            columns[1]: np.sin(seconds) + noise(),
            columns[2]: np.cos(seconds) + noise(),
            columns[3]: np.tan(seconds) + noise(),
            columns[4]: rng.choice(sensor_statuses, size=len(timestamps)),
        },
        columns=columns,
    )

