import re
import os
import glob

def task_func(dir_path: str) -> list:
    files = [
        path for path in glob.glob(os.path.join(dir_path, "*"))
        if os.path.isfile(path)
    ]

    renames = []
    new_names = set()

    for old_path in files:
        old_name = os.path.basename(old_path)
        new_name = re.sub(r"[^A-Za-z0-9]", "", old_name)

        if not new_name:
            raise ValueError(f"Cannot rename {old_name!r}: resulting name is empty.")

        if new_name in new_names:
            raise ValueError(f"Multiple files would be renamed to {new_name!r}.")

        new_names.add(new_name)
        renames.append((old_path, os.path.join(dir_path, new_name), new_name))

    source_paths = {old_path for old_path, _, _ in renames}
    for _, new_path, _ in renames:
        if os.path.exists(new_path) and new_path not in source_paths:
            raise FileExistsError(f"Target file already exists: {new_path}")

    for old_path, new_path, _ in renames:
        if old_path != new_path:
            os.rename(old_path, new_path)

    return [new_name for _, _, new_name in renames]

