import pandas as pd
import numpy as np
import matplotlib.pyplot as plt


def task_func(start_time, end_time, step, amplitude, period, seed=0):
    """Generate and plot a UTC time series with seasonal variation."""
    start = pd.Timestamp(start_time)
    end = pd.Timestamp(end_time)

    if start.tzinfo is None:
        start = start.tz_localize("UTC")
    else:
        start = start.tz_convert("UTC")

    if end.tzinfo is None:
        end = end.tz_localize("UTC")
    else:
        end = end.tz_convert("UTC")

    if end < start:
        raise ValueError("end_time must not be earlier than start_time")

    if isinstance(step, (int, float, np.number)):
        step_delta = pd.to_timedelta(step, unit="s")
    else:
        step_delta = pd.to_timedelta(step)

    if step_delta <= pd.Timedelta(0):
        raise ValueError("step must be positive")

    if isinstance(period, (int, float, np.number)):
        period_value = float(period)
        if period_value <= 0:
            raise ValueError("period must be positive")
        use_sample_period = True
    else:
        period_delta = pd.to_timedelta(period)
        if period_delta <= pd.Timedelta(0):
            raise ValueError("period must be positive")
        use_sample_period = False

    timestamps = pd.date_range(
        start=start,
        end=end,
        freq=step_delta,
        inclusive="both",
    )

    if use_sample_period:
        phase = np.arange(len(timestamps)) / period_value
    else:
        elapsed = (timestamps - timestamps[0]).total_seconds()
        phase = elapsed / period_delta.total_seconds()

    rng = np.random.RandomState(seed)
    seasonal_values = float(amplitude) * np.sin(2 * np.pi * phase)
    noise = rng.normal(loc=0.0, scale=0.1, size=len(timestamps))
    values = seasonal_values + noise

    data = pd.DataFrame({"Timestamp": timestamps, "Value": values})

    ax = data.plot(
        x="Timestamp",
        y="Value",
        figsize=(10, 5),
        legend=False,
        title="Time Series with Seasonality",
    )
    ax.set_xlabel("Timestamp")
    ax.set_ylabel("Value")
    ax.grid(True, alpha=0.3)
    return ax

