    result = defaultdict(list)

    def get_field(record, names):
        if isinstance(record, dict):
            for key, value in record.items():
                if str(key).lower() in names:
                    return value
        return None

    def add_salary(department, salary):
        if isinstance(department, str) and department.startswith(prefix):
            result[department].append(salary)

    for key, value in dict1.items():
        if isinstance(key, str) and key.startswith(prefix):
            if isinstance(value, dict):
                salary = get_field(value, {"salary"})
                if salary is not None:
                    add_salary(key, salary)
                else:
                    for item in value.values():
                        if not isinstance(item, dict):
                            add_salary(key, item)
                        else:
                            salary = get_field(item, {"salary"})
                            if salary is not None:
                                add_salary(key, salary)
            elif isinstance(value, (list, tuple, set)):
                for item in value:
                    salary = get_field(item, {"salary"}) if isinstance(item, dict) else item
                    if salary is not None:
                        add_salary(key, salary)
            else:
                add_salary(key, value)
        elif isinstance(value, dict):
