import pandas as pd
import numpy as np
import statsmodels.api as sm


def task_func(
    array: list, random_seed: int = 0
) -> (pd.DataFrame, sm.regression.linear_model.RegressionResultsWrapper):
    if not isinstance(array, list):
        raise TypeError("array must be a 2D list")

    if not isinstance(random_seed, (int, np.integer)) or isinstance(random_seed, bool):
        raise TypeError("random_seed must be an integer")

    if not array:
        raise ValueError("array must not be empty")

    if any(not isinstance(row, list) for row in array):
        raise TypeError("array must contain only lists")

    if any(len(row) != 5 for row in array):
        raise ValueError("each row must contain exactly five values")

    df = pd.DataFrame(array, columns=["A", "B", "C", "D", "Response"])

    for column in df.columns:
        df[column] = pd.to_numeric(df[column], errors="raise")

    if not np.isfinite(df.to_numpy(dtype=float)).all():
        raise ValueError("array must contain only finite numeric values")

    np.random.seed(int(random_seed))

    independent_variables = df[["A", "B", "C", "D"]]
    dependent_variable = df["Response"]

    independent_variables = sm.add_constant(independent_variables)
    results = sm.OLS(dependent_variable, independent_variables).fit()

    return df, results

import json
import csv


def task_func(json_file, csv_file):
    with open(json_file, "r", encoding="utf-8") as source:
        data = json.load(source)

    if isinstance(data, dict):
        rows = [data]
    elif isinstance(data, list):
        rows = data
    else:
        raise ValueError("JSON data must be an object or an array of objects")

    if not all(isinstance(row, dict) for row in rows):
        raise ValueError("Each JSON record must be an object")

    fieldnames = []
    for row in rows:
        for key in row:
            if key not in fieldnames:
                fieldnames.append(key)

    with open(csv_file, "w", encoding="utf-8", newline="") as target:
        if fieldnames:
            writer = csv.DictWriter(target, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerows(rows)

    return csv_file

