# Make sure to download NLTK stopwords
nltk.download('stopwords')
# Define a regex pattern for matching all non-alphanumeric characters
ALPHANUMERIC = re.compile('[\W_]+')
# Load NLTK's list of English stop words
STOPWORDS = nltk.corpus.stopwords.words('english')


def task_func(texts):
    processed_texts = [
        ALPHANUMERIC.sub(' ', text.lower())
        for text in texts
    ]

    vectorizer = CountVectorizer(stop_words=STOPWORDS)

    if not processed_texts:
        return pd.DataFrame()

    try:
        matrix = vectorizer.fit_transform(processed_texts)
    except ValueError as error:
        if "empty vocabulary" not in str(error):
            raise
        return pd.DataFrame(index=range(len(texts)))

    return pd.DataFrame(
        matrix.toarray(),
        columns=vectorizer.get_feature_names_out()
    )

import pandas as pd
from datetime import datetime, timedelta
from random import randint, seed as random_seed


def task_func(
    start_date=datetime(2020, 1, 1),
    end_date=datetime(2020, 12, 31),
    seed=42,
):
    if not isinstance(start_date, datetime) or not isinstance(end_date, datetime):
        raise ValueError("'start_date' and 'end_date' must be datetime.datetime instances")

    if start_date > end_date:
        raise ValueError("'start_date' cannot be later than 'end_date'")

    random_seed(seed)

    number_of_days = (end_date - start_date).days
    dates = [
        start_date + timedelta(days=randint(0, number_of_days))
        for _ in range(number_of_days + 1)
    ]

    return pd.Series(dates)

import pandas as pd
import pytz


def task_func(articles, timezone):
    if not isinstance(articles, list) or not all(
        isinstance(article, dict) for article in articles
    ):
        raise TypeError("articles must be a list of dictionaries")

    if not articles:
        raise ValueError("articles must not be empty")

    required_keys = {"published_time", "category"}
    if any(set(article.keys()) != required_keys for article in articles):
        raise ValueError(
            "Each article dictionary must contain exactly "
            "'published_time' and 'category' keys"
        )

    target_timezone = pytz.timezone(timezone)
    data = pd.DataFrame(articles)

    timestamps = pd.to_datetime(data["published_time"], utc=True)
    data["publication_hour"] = (
        timestamps.dt.tz_convert(target_timezone).dt.hour
    )

    result = data.groupby("category")["publication_hour"].agg(
        count="count",
        mean="mean",
        min="min",
        max="max",
    )

    result.index.name = "category"
    return result

