def task_func(data=None):
    """Convert, threshold, and standardize a numeric dataset."""
    if data is None:
        return pd.DataFrame()

    if isinstance(data, pd.DataFrame):
        dataframe = data.copy()
    else:
        dataframe = pd.DataFrame(data)

    if dataframe.empty:
        return dataframe.astype(float)

    dataframe = dataframe.mask(dataframe < 0.5, 0)
    scaler = StandardScaler()
    standardized = scaler.fit_transform(dataframe)

    return pd.DataFrame(
        standardized,
        index=dataframe.index,
        columns=dataframe.columns,
    )

