import subprocess
import psutil
import time
import os


def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    cpu_usage = 0.0
    memory_usage = 0
    process = subprocess.Popen(["bash", script_path])
    monitored_process = None
    start_time = time.monotonic()
    deadline = start_time + max(0.0, float(timeout))

    try:
        monitored_process = psutil.Process(process.pid)
        monitored_process.cpu_percent(None)

        while process.poll() is None:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                process.terminate()
                try:
                    process.wait(timeout=1)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait()
                break

            try:
                if not monitored_process.is_running():
                    break

                if monitored_process.status() == psutil.STATUS_ZOMBIE:
                    break

                sample_interval = min(0.1, remaining)
                cpu_usage += monitored_process.cpu_percent(
                    interval=sample_interval
                )
                memory_usage += monitored_process.memory_info().rss

            except (
                psutil.NoSuchProcess,
                psutil.ZombieProcess,
                psutil.AccessDenied,
            ):
                break

        if process.poll() is None:
            process.wait()

    finally:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()

    return {
        "CPU Usage": cpu_usage,
        "Memory Usage": memory_usage,
    }

