def task_func(password_length=10, salt="salty"):
    if not isinstance(password_length, int) or isinstance(password_length, bool):
        raise TypeError("password_length must be an integer")
    if password_length < 0:
        raise ValueError("password_length must be non-negative")
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")

    characters = string.ascii_letters + string.digits + string.punctuation
