import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    result = data.copy()

    keys = [
        key for key in mapping
        if isinstance(key, str) and key
    ]

    if not keys:
        return result

    keys.sort(key=len, reverse=True)
    pattern = re.compile(
        r"(?<!\w)(?:" + "|".join(re.escape(key) for key in keys) + r")(?!\w)"
    )

    def replace_acronyms(value):
        if not isinstance(value, str):
            return value

        return pattern.sub(
            lambda match: str(mapping[match.group(0)]),
            value
        )

    return result.applymap(replace_acronyms)

import random
import bisect
from array import array

def task_func(n=10, total=100):
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(total, int) or total < 0:
        raise ValueError("total must be a non-negative integer")
    if n == 0:
        if total != 0:
            raise ValueError("total must be zero when n is zero")
        numbers = []
    else:
        while True:
            remaining = total
            numbers = []

            for index in range(n - 1):
                value = random.randint(0, remaining)
                numbers.append(value)
                remaining -= value

            numbers.append(remaining)

            if sum(numbers) == total:
                break

    numbers.sort()
    sorted_numbers = array("i", numbers)
    new_number = random.randint(0, total)
    insertion_position = bisect.bisect_left(sorted_numbers, new_number)

    return sorted_numbers, insertion_position

