import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    if 'value' not in df.columns:
        raise ValueError("df must contain a 'value' column")

    if not isinstance(freq, str) or not freq.strip():
        raise ValueError("freq must be a valid frequency string")

    try:
        offset = pd.tseries.frequencies.to_offset(freq)
    except (TypeError, ValueError):
        raise ValueError("freq must be a valid frequency string")

    if decomposition_model not in {'additive', 'multiplicative'}:
        raise ValueError(
            "decomposition_model must be 'additive' or 'multiplicative'"
        )

    values = df['value']
    if (
        not pd.api.types.is_numeric_dtype(values)
        or pd.api.types.is_bool_dtype(values)
        or values.isna().any()
        or not values.map(pd.api.types.is_number).all()
    ):
        raise ValueError("'value' must contain valid numeric data")

    if not values.map(pd.api.types.is_number).all():
        raise ValueError("'value' must contain valid numeric data")

    if not pd.Series(values).map(lambda x: pd.notna(x) and pd.api.types.is_number(x)).all():
        raise ValueError("'value' must contain valid numeric data")

    if not pd.Series(values).astype(float).map(lambda x: pd.notna(x) and pd.np.isfinite(x)).all():
        raise ValueError("'value' must contain finite numeric data")

    if 'date' in df.columns:
        if not pd.api.types.is_datetime64_any_dtype(df['date']):
            raise ValueError("'date' must contain datetime data")

        dates = pd.DatetimeIndex(df['date'])
        if dates.has_duplicates:
            raise ValueError("'date' must not contain duplicates")

        order = dates.argsort()
        dates = dates[order]
        values = values.iloc[order].reset_index(drop=True)
    elif isinstance(df.index, pd.DatetimeIndex):
        if df.index.has_duplicates:
            raise ValueError("the datetime index must not contain duplicates")

        dates = df.index.sort_values()
        values = df.loc[dates, 'value'].reset_index(drop=True)
    else:
        dates = pd.date_range(
            start='2000-01-01',
            periods=len(df),
            freq=offset
        )
        values = values.reset_index(drop=True)

    try:
        index = pd.DatetimeIndex(dates, freq=offset)
    except (TypeError, ValueError):
        raise ValueError("the time index does not match freq")

    series = pd.Series(values.to_numpy(dtype=float), index=index, name='value')

    try:
        decomposition = seasonal_decompose(
            series,
            model=decomposition_model,
            period=None
        )
        figure = decomposition.plot()
        ax = figure.axes[0]
    except Exception as exc:
        raise ValueError("unable to decompose the supplied time series") from exc

    return decomposition, ax

