import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)
    if not directory.is_dir():
        raise FileNotFoundError(f"Directory does not exist: {dir_path}")

    valid_predicates = []
    seen = set()

    for predicate in predicates:
        if callable(predicate):
            key = ("callable", id(predicate))
        elif isinstance(predicate, str):
            try:
                compiled = re.compile(predicate)
            except re.error:
                continue
            predicate = compiled
            key = ("regex", compiled.pattern, compiled.flags)
        elif isinstance(predicate, re.Pattern):
            key = ("regex", predicate.pattern, predicate.flags)
        else:
            continue

        if key not in seen:
            seen.add(key)
            valid_predicates.append(predicate)

    if not valid_predicates:
        raise ValueError("No valid predicates were provided")

    result = {}
    for item_name in os.listdir(directory):
        checks = []

        for predicate in valid_predicates:
            if callable(predicate) and not isinstance(predicate, re.Pattern):
                checks.append(bool(predicate(item_name)))
            else:
                checks.append(predicate.search(item_name) is not None)

        result[item_name] = checks

    return result

import os
import shutil

def task_func(src_dir, dest_dir, extension):
    if not os.path.isdir(src_dir):
        raise FileNotFoundError(f"Source directory does not exist: {src_dir}")

    if os.path.abspath(src_dir) == os.path.abspath(dest_dir):
        return 0

    os.makedirs(dest_dir, exist_ok=True)

    files_moved = 0
    for filename in os.listdir(src_dir):
        source_path = os.path.join(src_dir, filename)

        if os.path.isfile(source_path) and filename.endswith(extension):
            shutil.move(source_path, os.path.join(dest_dir, filename))
            files_moved += 1

    return files_moved

