# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df, tuples, n_plots):
    """Remove matching rows and create random two-column line plots."""
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    rules = tuples
    if isinstance(tuples, tuple) and len(tuples) == len(COLUMNS):
        rules = [tuples]

    filtered_df = df.copy()

    for rule in rules:
        if isinstance(rule, dict):
            conditions = []
            for column, value in rule.items():
                if column not in COLUMNS:
                    raise ValueError(f"Unknown column: {column}")
                conditions.append(
                    filtered_df[column].eq(value)
                    | (filtered_df[column].isna() & value != value)
                )
            if conditions:
                matches = conditions[0]
                for condition in conditions[1:]:
                    matches &= condition
                filtered_df = filtered_df.loc[~matches]
            continue

        if len(rule) == len(COLUMNS):
            conditions = [
                filtered_df[column].eq(value)
                | (filtered_df[column].isna() & value != value)
                for column, value in zip(COLUMNS, rule)
            ]
        elif (
            len(rule) == 2
            and isinstance(rule[0], str)
            and rule[0] in COLUMNS
        ):
            conditions = [
                filtered_df[rule[0]].eq(rule[1])
                | (filtered_df[rule[0]].isna() & rule[1] != rule[1])
            ]
        elif all(
            isinstance(item, (tuple, list))
            and len(item) == 2
            and item[0] in COLUMNS
            for item in rule
        ):
            conditions = [
                filtered_df[column].eq(value)
                | (filtered_df[column].isna() & value != value)
                for column, value in rule
            ]
        else:
            raise ValueError("Each rule must specify valid column values")

        matches = conditions[0]
        for condition in conditions[1:]:
            matches &= condition
        filtered_df = filtered_df.loc[~matches]

    plot_details = []
    for _ in range(n_plots):
        x_column, y_column = sample(COLUMNS, 2)
        plt.plot(filtered_df[x_column], filtered_df[y_column])
        plot_details.append((x_column, y_column))

    return filtered_df, plot_details

