from gensim.models import Word2Vec
# Constants
ALPHANUMERIC = re.compile('[\W_]+')


def task_func(texts, stopwords=None):
    """Train and return a Word2Vec model from cleaned input texts."""
    if stopwords is None:
        stopwords = nltk.corpus.stopwords.words("english")

    stopword_set = {word.lower() for word in stopwords}
    tokenized_texts = []

    for text in texts:
        if not isinstance(text, str):
            raise TypeError("Each text must be a string.")

        cleaned_text = ALPHANUMERIC.sub(" ", text.lower())
        tokens = [
            token
            for token in cleaned_text.split()
            if token not in stopword_set
        ]
        if tokens:
            tokenized_texts.append(tokens)

    if not tokenized_texts:
        raise ValueError("No tokens remain after text cleaning and stop-word removal.")

    return Word2Vec(
        sentences=tokenized_texts,
        vector_size=100,
        window=5,
        min_count=1,
        workers=1,
        seed=42,
    )

