import pandas as pd
import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(start_date='2016-01-01', periods=24, freq='M', model='additive'):
    """Generate a synthetic sales series and decompose it."""

    if periods <= 0:
        raise ValueError("periods must be a positive integer")

    model = model.lower()
    if model not in {"additive", "multiplicative"}:
        raise ValueError("model must be 'additive' or 'multiplicative'")

    frequency = str(freq).upper()
    if frequency.startswith(("M", "BM")):
        seasonal_period = 12
    elif frequency.startswith(("Q", "BQ")):
        seasonal_period = 4
    elif frequency.startswith("W"):
        seasonal_period = 52
    elif frequency.startswith("D"):
        seasonal_period = 7
    elif frequency.startswith(("H", "BH")):
        seasonal_period = 24
    else:
        seasonal_period = 12

    if periods < 2 * seasonal_period:
        raise ValueError(
            f"periods must be at least {2 * seasonal_period} for frequency {freq!r}"
        )

    dates = pd.date_range(
        start=start_date,
        periods=periods,
        freq=freq,
    )

    time = np.arange(periods, dtype=float)
    trend = 100 + 2.5 * time
    seasonal_pattern = 1 + 0.12 * np.sin(
        2 * np.pi * time / seasonal_period
    )
    noise = 1 + 0.02 * np.cos(2 * np.pi * time / seasonal_period * 3)

    if model == "multiplicative":
        sales = trend * seasonal_pattern * noise
    else:
        seasonal_component = 12 * np.sin(
            2 * np.pi * time / seasonal_period
        )
        sales = trend + seasonal_component + 2 * np.cos(
            2 * np.pi * time / seasonal_period * 3
        )

    sales_series = pd.Series(sales, index=dates, name="sales")

    decomposition = seasonal_decompose(
        sales_series,
        model=model,
        period=seasonal_period,
    )

    return {
        "trend": decomposition.trend,
        "seasonal": decomposition.seasonal,
        "residual": decomposition.resid,
    }

