    sample = rng.normal(loc=mu, scale=sigma, size=sample_size)
    x = np.linspace(mu - 4 * sigma, mu + 4 * sigma, 1000)

    if sample_size > 1:
        try:
            density = stats.gaussian_kde(sample)(x)
        except np.linalg.LinAlgError:
            bandwidth = sigma * sample_size ** (-1 / 5)
            density = np.mean(
                stats.norm.pdf(
                    x[:, None],
                    loc=sample[None, :],
                    scale=bandwidth,
                ),
                axis=1,
            )
    else:
        density = stats.norm.pdf(x, loc=sample[0], scale=sigma)

    _, ax = plt.subplots()
    ax.plot(x, density)
    return ax

