import warnings
import os
import glob
import shutil
import time


def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    """Copy files with the requested extensions from SOURCE_DIR to DEST_DIR."""
    transferred_files = []

    if not isinstance(SOURCE_DIR, (str, os.PathLike)):
        warnings.warn("SOURCE_DIR must be a path.", RuntimeWarning)
        return transferred_files

    if not isinstance(DEST_DIR, (str, os.PathLike)):
        warnings.warn("DEST_DIR must be a path.", RuntimeWarning)
        return transferred_files

    if isinstance(EXTENSIONS, (str, os.PathLike)):
        extensions = [str(EXTENSIONS)]
    else:
        try:
            extensions = list(EXTENSIONS)
        except TypeError:
            warnings.warn("EXTENSIONS must be an iterable.", RuntimeWarning)
            return transferred_files

    source_dir = os.fspath(SOURCE_DIR)
    dest_dir = os.fspath(DEST_DIR)

    if not os.path.isdir(source_dir):
        warnings.warn(f"Source directory does not exist: {source_dir}", RuntimeWarning)
        return transferred_files

    try:
        os.makedirs(dest_dir, exist_ok=True)
    except OSError as exc:
        warnings.warn(f"Could not create destination directory: {exc}", RuntimeWarning)
        return transferred_files

    normalized_extensions = set()
    for extension in extensions:
        extension = str(extension).strip()
        if extension:
            normalized_extensions.add(
                extension if extension.startswith(".") else f".{extension}"
            )

    for path in glob.glob(os.path.join(source_dir, "*")):
        if not os.path.isfile(path):
            continue

        if os.path.splitext(path)[1] not in normalized_extensions:
            continue

        filename = os.path.basename(path)
        destination = os.path.join(dest_dir, filename)

        try:
            shutil.copy2(path, destination)
            transferred_files.append(filename)
        except Exception as exc:
            warnings.warn(
                f"Could not transfer {filename!r}: {exc}",
                RuntimeWarning,
            )

    return transferred_files

