import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if pattern == "":
        return df.copy()

    regex = re.compile(pattern)

    def reverse_matching_words(value):
        if not isinstance(value, str):
            return value

        words = value.split()
        matching_words = [word for word in words if regex.search(word)]
        matching_words.reverse()

        matching_index = 0
        for index, word in enumerate(words):
            if regex.search(word):
                words[index] = matching_words[matching_index]
                matching_index += 1

        return " ".join(words)

    result = df.copy()
    result[column_name] = result[column_name].apply(reverse_matching_words)
    return result

