import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    if not os.path.isfile(file_path):
        raise ValueError("JSON file does not exist")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError("Unable to read valid JSON file") from exc

    if INPUT_JSON.get("type") == "object" and not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    for field in required:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")

    for field, schema in properties.items():
        if field not in data:
            continue

        expected_type = schema.get("type")
        value = data[field]

        if expected_type is int and isinstance(value, bool):
            raise ValueError(f"Invalid type for attribute: {field}")

        if expected_type is not None and not isinstance(value, expected_type):
            raise ValueError(f"Invalid type for attribute: {field}")

    if "email" in data:
        if not isinstance(data["email"], str) or re.fullmatch(
            EMAIL_REGEX, data["email"]
        ) is None:
            raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute not found: {attribute}")

    return data[attribute]

