import ssl
import os
import hashlib

def task_func(client_socket, cert_file, key_file, buffer_size=1024):
    secure_socket = None

    try:
        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(certfile=cert_file, keyfile=key_file)
        secure_socket = context.wrap_socket(client_socket, server_side=True)

        file_path = secure_socket.recv(buffer_size).decode("utf-8").strip()

        if not os.path.exists(file_path):
            response = "File not found"
        else:
            file_hash = hashlib.sha256()
            with open(file_path, "rb") as requested_file:
                while chunk := requested_file.read(buffer_size):
                    file_hash.update(chunk)
            response = file_hash.hexdigest()

        secure_socket.sendall(response.encode("utf-8"))
        return response

    except Exception as error:
        response = f"Error: {error}"
        try:
            if secure_socket is not None:
                secure_socket.sendall(response.encode("utf-8"))
        except Exception:
            pass
        return response

