from typing import List


def task_func(source_dir: str, target_dir: str, extensions: List[str]) -> int:
    source_path = Path(source_dir)
    target_path = Path(target_dir)

    if not source_path.exists() or not target_path.exists():
        raise ValueError("Source and target directories must exist.")

    if not source_path.is_dir() or not target_path.is_dir():
        raise ValueError("Source and target paths must be directories.")

    normalized_extensions = {
        extension.lower() if extension.startswith(".") else f".{extension.lower()}"
        for extension in extensions
    }

    moved_count = 0

    for file_path in source_path.iterdir():
        if file_path.is_file() and file_path.suffix.lower() in normalized_extensions:
            shutil.move(str(file_path), str(target_path / file_path.name))
            moved_count += 1

    return moved_count

