import pandas as pd


def task_func(directory='./', file_pattern='*.txt', regex=r'([0-9]+)'):
    """Extract numeric data from matching text files into a DataFrame."""
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"Directory does not exist: {directory}")

    file_paths = glob.glob(os.path.join(directory, file_pattern))
    if not file_paths:
        raise ValueError(f"No files matching pattern found: {file_pattern}")

    rows = []
    for file_path in natsort.natsorted(file_paths):
        with open(file_path, "r", encoding="utf-8") as file:
            content = file.read()

        rows.append({
            "Filename": os.path.basename(file_path),
            "Numeric Data": re.findall(regex, content),
        })

    return pd.DataFrame(rows, columns=["Filename", "Numeric Data"])

