from datetime import datetime
from datetime import timedelta

def task_func(rows=3, columns=2, start_date=datetime(2021, 1, 1), end_date=datetime(2021, 12, 31), seed=0):
    if not isinstance(rows, (int, np.integer)) or not isinstance(columns, (int, np.integer)):
        raise TypeError("rows and columns must be integers")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")
    if not isinstance(start_date, datetime) or not isinstance(end_date, datetime):
        raise TypeError("start_date and end_date must be datetime objects")
    if end_date < start_date:
        raise ValueError("end_date must not be earlier than start_date")

    total_values = rows * columns
    available_days = (end_date.date() - start_date.date()).days + 1

    if total_values > available_days:
        raise ValueError("The date range does not contain enough unique dates")

    rng = random.Random(seed)
    day_offsets = rng.sample(range(available_days), total_values)
    dates = [
        start_date + timedelta(days=offset)
        for offset in day_offsets
    ]

    return np.array(dates).reshape(rows, columns)

