import inspect
import types
import json


def task_func(f):
    signature = inspect.signature(f)

    arguments = []
    defaults = {}

    for parameter in signature.parameters.values():
        arguments.append(parameter.name)
        if parameter.default is not inspect.Parameter.empty:
            defaults[parameter.name] = parameter.default

    annotations = {
        name: str(annotation)
        for name, annotation in getattr(f, "__annotations__", {}).items()
    }

    specifications = {
        "name": getattr(f, "__name__", str(f)),
        "args": arguments,
        "defaults": defaults,
        "annotations": annotations,
        "is_lambda": isinstance(f, types.LambdaType)
        and getattr(f, "__name__", "") == "<lambda>",
    }

    return json.dumps(specifications, default=str)

