# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    if (
        not isinstance(date_str, str)
        or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_str)
    ):
        raise ValueError("date_str must follow the yyyy-mm-dd format")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str must be a valid date") from exc

    if requested_date < datetime.now().date():
        raise ValueError("date_str must not refer to a past date")

    def extract_status(value):
        if isinstance(value, dict):
            return value.get(
                "status",
                value.get("booking_status", value.get("Status", "Available")),
            )
        return value if value is not None else "Available"

    statuses = {room: "Available" for room in ROOMS}

    if isinstance(booking_data, pd.DataFrame):
        records = booking_data.to_dict("records")
        for record in records:
            record_date = record.get("date", record.get("Date"))
            if record_date is not None and str(record_date)[:10] != date_str:
                continue
            room = record.get("room", record.get("Room"))
            if room in statuses:
                statuses[room] = extract_status(record)

    elif isinstance(booking_data, dict):
        date_data = booking_data.get(date_str)

        if date_data is None:
            date_data = booking_data.get(requested_date)

        if date_data is None:
            date_data = booking_data

        if isinstance(date_data, dict):
            for room in ROOMS:
                if room in date_data:
                    statuses[room] = extract_status(date_data[room])

        elif isinstance(date_data, (list, tuple)):
            for record in date_data:
                if not isinstance(record, dict):
                    continue
                room = record.get("room", record.get("Room"))
                if room in statuses:
                    statuses[room] = extract_status(record)

    elif isinstance(booking_data, (list, tuple)):
        for record in booking_data:
            if not isinstance(record, dict):
                continue
            record_date = record.get("date", record.get("Date"))
            if record_date is not None and str(record_date)[:10] != date_str:
                continue
            room = record.get("room", record.get("Room"))
            if room in statuses:
                statuses[room] = extract_status(record)

    report = pd.DataFrame(
        {
            "Room": ROOMS,
            "Status": [statuses[room] for room in ROOMS],
        }
    )

    ax = report["Status"].value_counts().plot(
        kind="bar",
        color="steelblue",
        figsize=(8, 5),
    )
    ax.set_title(f"Room Booking Statuses for {date_str}")
    ax.set_xlabel("Booking Status")
    ax.set_ylabel("Number of Rooms")
    ax.tick_params(axis="x", rotation=0)
    ax.figure.tight_layout()

    return report, ax

