from itertools import combinations
from random import sample
def task_func(df, tuples, n_plots):
    import pandas as pd
    import matplotlib.pyplot as plt

    rows_to_remove = list(tuples)

    def values_equal(left, right):
        try:
            left_missing = bool(pd.isna(left))
        except (TypeError, ValueError):
            left_missing = False
        try:
            right_missing = bool(pd.isna(right))
        except (TypeError, ValueError):
            right_missing = False

        if left_missing or right_missing:
            return left_missing and right_missing

        try:
            return bool(left == right)
        except (TypeError, ValueError):
            return False

    def row_matches(row, values):
        return (
            len(values) == len(row)
            and all(values_equal(cell, value) for cell, value in zip(row, values))
        )

    mask = df.apply(
        lambda row: any(row_matches(row.tolist(), values) for values in rows_to_remove),
        axis=1,
    )
    remaining_df = df.loc[~mask]

    column_combinations = list(combinations(remaining_df.columns, 2))
    plot_count = max(0, min(int(n_plots), len(column_combinations)))
    selected_combinations = sample(column_combinations, plot_count)

    plots = []
    for columns in selected_combinations:
        fig, ax = plt.subplots()
        ax.scatter(remaining_df[columns[0]], remaining_df[columns[1]])
        ax.set_xlabel(columns[0])
        ax.set_ylabel(columns[1])
        plots.append((columns, ax))

    return remaining_df, plots

