import os
from pathlib import Path
import glob
import shutil


def task_func(source_directory: str, target_directory: str):
    source_path = Path(source_directory)
    target_path = Path(target_directory)

    if not source_path.exists():
        raise FileNotFoundError(source_directory)

    target_path.mkdir(parents=True, exist_ok=True)

    allowed_extensions = {".txt", ".docx", ".xlsx", ".csv"}
    files = [
        Path(path)
        for path in glob.glob(
            os.path.join(str(source_path), "**", "*"),
            recursive=True,
        )
        if os.path.isfile(path)
        and Path(path).suffix.lower() in allowed_extensions
    ]

    moved_count = 0

    for file_path in files:
        destination = target_path / file_path.name

        if destination.exists():
            counter = 1
            while True:
                candidate = (
                    target_path
                    / f"{file_path.stem}-{counter}{file_path.suffix}"
                )
                if not candidate.exists():
                    destination = candidate
                    break
                counter += 1

        shutil.move(str(file_path), str(destination))
        moved_count += 1

    return moved_count

