def task_func(data):
    if len(data) < 2:
        return float("nan")

    scores = pd.to_numeric(data["score"], errors="coerce")
    grades = pd.Categorical(
        data["grade"],
        categories=sorted(data["grade"].dropna().unique()),
        ordered=True,
    ).codes

