import collections
from queue import PriorityQueue
import random
# Constants
LETTERS = ['a', 'b', 'c', 'd', 'e']

def task_func(string_length=100):
    if not isinstance(string_length, int):
        raise TypeError("string_length must be an integer")
    if string_length < 0:
        raise ValueError("string_length must be non-negative")

    generated_string = ''.join(
        random.choice(LETTERS) for _ in range(string_length)
    )

    frequencies = {letter: 0 for letter in LETTERS}
    for letter in generated_string:
        frequencies[letter] += 1

    priority_queue = PriorityQueue()
    for index, letter in enumerate(LETTERS):
        priority_queue.put((-frequencies[letter], index, letter))

    ordered_frequencies = collections.OrderedDict()
    while not priority_queue.empty():
        _, _, letter = priority_queue.get()
        ordered_frequencies[letter] = frequencies[letter]

    return ordered_frequencies

