import re
import shutil


def task_func(source_directory: str, target_directory: str, pattern: str = r"\d{4}") -> int:
    if not os.path.isdir(source_directory):
        return 0

    regex = re.compile(pattern)

    try:
        os.makedirs(target_directory, exist_ok=True)
    except OSError:
        return 0

    moved_count = 0

    try:
        entries = os.scandir(source_directory)
    except OSError:
        return 0

    with entries:
        for entry in entries:
            if not entry.is_file() or not regex.search(entry.name):
                continue

            destination = os.path.join(target_directory, entry.name)

            try:
                shutil.move(entry.path, destination)
            except OSError:
                continue

            moved_count += 1

    return moved_count

