import re
import os
import glob
from pathlib import Path


def task_func(pattern, directory, extensions):
    regex = re.compile(pattern, re.IGNORECASE)
    directory_path = Path(directory).expanduser().resolve()

    if isinstance(extensions, str):
        extensions = [extensions]

    normalized_extensions = None
    if extensions:
        normalized_extensions = {
            ext.lower() if str(ext).startswith(".") else f".{str(ext).lower()}"
            for ext in extensions
        }

    matching_files = []

    for file_path in glob.glob(str(directory_path / "*")):
        path = Path(file_path)

        if not path.is_file():
            continue

        if normalized_extensions and path.suffix.lower() not in normalized_extensions:
            continue

        try:
            with path.open("r", encoding="utf-8", errors="ignore") as file:
                if regex.search(file.read()):
                    matching_files.append(str(path.resolve()))
        except (OSError, UnicodeError):
            continue

    return sorted(matching_files)

